// Pawn Champ - Out of Habit: the Wolf Moon's echo (minor, the month after a cure). Round 3, batch S.
// docs/quests/MAJOR.md#the-wolf-moon-m4s-long-arc. Bettany comes in at dusk on the full moon, in the
// ears, out of habit. Its code half is The Wolf Moon's (js/quests/wolfmoon.js).
//
// Written as data: docs/STORY_DATA.md. Strict JSON inside the call.
defineStory({
  "id": "psalterEcho",
  "kind": "minor",
  "family": "uncanny",
  "colour": "#b08ad0",
  "title": "Out of Habit",
  "sequel": "psalter",
  "after": ["amber", "silver", "ink", "returned"],
  "teaser": "The full moon is on Wednesday. Somebody has left a pair of felt ears on the bakery's step.",
  "rumour": "Bettany Lowe has been humming at the full moon again.",
  "endings": { "home": "Gone Home", "relapse": "Out of Habit" },
  "outcome": "flag.echoEnd",
  "code": "wolfmoon",
  "about": [
    "A small coda to The Grey Psalter, for a run after the Pack was broken. On a full moon in week 2 or 3, Bettany comes to the counter at dusk in her felt ears, not knowing why, needing something silver for a Moon Table that no longer exists (§{psalterEcho}).",
    "Talk her home, or give her a cup of tea, and she goes back to the bread (Gone Home, and she warms to you). Sell her the silver, and she puts it on a rock behind the bakery and howls once, a bit flat (Out of Habit). It's a gentle scene about an aftermath, not a threat."
  ],
  "scenes": {
    "psalterEcho": {
      "title": "Bettany at dusk on the full moon, in the ears, out of habit",
      "customer": "bettany",
      "steps": [
        {
          "say": "bettany",
          "text": [
            "Evening. Don't look at the ears. I don't know why I'm wearing the ears. I was making the bread and then I was walking here.",
            "The moon's up. I need something silver for the Moon Table. There isn't a Moon Table any more, I know that. I just need it."
          ]
        },
        {
          "choose": [
            {
              "label": "\"Bettany, the Pack's gone. Go home and make the bread.\"",
              "then": [
                { "set": { "echoEnd": "home" } },
                { "rep": 1 },
                { "sway": "bettany", "by": 1, "why": "Talked her home on the full moon" },
                { "say": "bettany", "text": "Bread. Yes. The bread. ...Thank you. Don't tell anyone. Tell Rosa, if she asks. She'll ask." }
              ]
            },
            {
              "label": "Sell her something silver",
              "then": [
                { "hook": "cultSale", "with": { "cats": ["silver"], "mult": 1.2 }, "sets": ["sold"] },
                { "set": { "echoEnd": "relapse" } },
                {
                  "say": "bettany",
                  "text": { "if": "sold", "then": "Thank you. I'll put it on a rock. Any rock. That's probably fine.", "else": "No? No. That's probably for the best." }
                },
                { "narrate": "From the end of the street, a single howl, a bit flat. Then a door shuts." }
              ]
            },
            {
              "label": "\"How about a cup of tea first?\"",
              "then": [
                { "set": { "echoEnd": "home" } },
                { "rep": 1 },
                { "sway": "bettany", "by": 1, "why": "Talked her home on the full moon" },
                { "narrate": "She drinks it standing up, at the counter. Halfway down the cup she takes the ears off, and looks at them, and puts them in her apron pocket." },
                { "say": "bettany", "text": "Bread. Yes. The bread. ...Thank you. Don't tell anyone. Tell Rosa, if she asks. She'll ask." }
              ]
            }
          ]
        },
        { "leave": "bettany" }
      ]
    }
  },
  "beats": [
    { "at": "2-3", "cast": "bettanyPack", "scene": "psalterEcho", "if": "!flag.echoEnd" },
    { "at": "3-3", "cast": "bettanyPack", "scene": "psalterEcho", "if": "!flag.echoEnd" }
  ],
  "epilogue": [
    { "line": "Bettany Lowe keeps the felt ears in her apron pocket, and on full moons she bakes all night instead.", "if": "flag.echoEnd == 'home'" },
    { "line": "On full moons, someone on Front Street still howls, once, a bit flat, and then goes back to the bread.", "if": "flag.echoEnd == 'relapse'" }
  ],
  "talk": {
    "by": "bettany",
    "rumour": [
      "I don't want to talk about the ears. I've put them in a drawer. Mostly they stay in the drawer.",
      "The full moon's Wednesday. I'm going to bake all night. That's the plan."
    ],
    "react": { "home": "I baked all night. Forty loaves. Nobody needed forty loaves. I'm fine.", "relapse": "I don't remember Wednesday. There's a silver spoon on a rock behind the bakery. I've left it there." },
    "sway": { "home": { "bettany": 1 }, "relapse": { "bettany": -1 } }
  }
});
